	/**
	 * Get rid of any resources this plugin is using before the plugin is destroyed.
	 */
	/* @Override */
	public void dispose() {
		navUpdater.dispose();

		tool.removePopupActionProvider(this);
		if (repaintMgr != null) {
			repaintMgr.dispose();
		}
		if (addAction != null) {
			addAction.dispose();
			addAction = null;
		}
		if (provider != null) {
			provider.dispose();
			provider = null;
		}
		goToService = null;

		disposeAllBookmarkers();
		markerService = null;

		if (currentProgram != null) {
			currentProgram.removeListener(domainObjectListener);
		}
		currentProgram = null;
		base.dispose();
	}

	/**
	 * Acquires <code>GoToService</code> if available.
	 */
	/* @Override */
	protected void init() {
		goToService = tool.getService(typeof(GoToService));
		provider.setGoToService(goToService);
		markerService = tool.getService(typeof(MarkerService));

		tool.addPopupActionProvider(this);

		navUpdater = new NavUpdater();
		repaintMgr = new SwingUpdateManager(500, () => provider.repaint());

	}

	MarkerService getMarkerService() {
		return markerService;
	}

	private void initializeBookmarkers() {
		if (currentProgram == null) {
			return;
		}

		BookmarkManager mgr = currentProgram.getBookmarkManager();
		BookmarkNavigator.defineBookmarkTypes(currentProgram);

		Runnable r = () => {
			if (currentProgram == null) {
				return;
			}
			lock (this) {
				// Initialize markers after all plugins have defined the various bookmark types
				BookmarkType[] types = mgr.getBookmarkTypes();
				foreach (BookmarkType element in types) {
					getBookmarkNavigator(element);
					scheduleUpdate(element.getTypeString());
				}
			}
		};
		SwingUtilities.invokeLater(r);
	}

	private void disposeAllBookmarkers() {
		foreach (BookmarkNavigator nav in bookmarkNavigators.values()) {
			nav.dispose();
		}
		bookmarkNavigators.clear();
	}

	/**
	 * Get or create a bookmark navigator for the specified bookmark type
	 * 
	 * @param type the bookmark type
	 * @return bookmark navigator
	 */
	private BookmarkNavigator getBookmarkNavigator(BookmarkType type) {
		if (type == null) {
			return null;
		}

		string typeString = type.getTypeString();
		BookmarkNavigator nav = bookmarkNavigators.get(typeString);
		if (nav != null) {
			return nav;
		}

		BookmarkManager bookmarkManager = currentProgram.getBookmarkManager();
		nav = new BookmarkNavigator(markerService, bookmarkManager, type);
		bookmarkNavigators.put(typeString, nav);
		return nav;
	}

	private void scheduleUpdate(string type) {
		navUpdater.addType(type);
	}

	public void reload() {
		scheduleUpdate(null);
		provider.reload();
	}

	/* @Override */
	public void setBookmarksVisible(bool visible) {
		tool.showComponentProvider(provider, visible);
	}

	private void typeAdded(ProgramChangeRecord rec) {
		BookmarkType type = (BookmarkType) rec.getObject();
		if (type == null) {
			return;
		}
		provider.typeAdded(type.getTypeString());
		getBookmarkNavigator(bookmarkMgr.getBookmarkType(type.getTypeString()));
		repaintMgr.update();
	}

	private void bookmarkChanged(ProgramChangeRecord rec) {
		Bookmark bookmark = (Bookmark) rec.getObject();
		if (bookmark == null) {
			scheduleUpdate(null);
			provider.reload();
			return;
		}
		BookmarkNavigator nav = getBookmarkNavigator(bookmark.getType());
		nav.add(bookmark.getAddress());
		scheduleUpdate(bookmark.getType().getTypeString());
		provider.bookmarkChanged(bookmark);
		repaintMgr.update();
	}

	private void bookmarkAdded(ProgramChangeRecord rec) {
		Bookmark bookmark = (Bookmark) rec.getObject();
		if (bookmark == null) {
			scheduleUpdate(null);
			provider.reload();
			return;
		}
		BookmarkNavigator nav = getBookmarkNavigator(bookmark.getType());
		nav.add(bookmark.getAddress());
//		scheduleUpdate(bookmark.getType().getTypeString());
		provider.bookmarkAdded(bookmark);
		repaintMgr.update();
	}

	private void bookmarkRemoved(ProgramChangeRecord rec) {
		Bookmark bookmark = (Bookmark) rec.getObject();
		if (bookmark == null) {
			scheduleUpdate(null);
			provider.reload();
			return;
		}
		string type = bookmark.getTypeString();
		BookmarkNavigator nav = bookmarkNavigators.get(type);
		if (nav != null) {
			Address addr = bookmark.getAddress();
			Bookmark[] bookmarks = currentProgram.getBookmarkManager().getBookmarks(addr, type);
			if (bookmarks.length == 0) {
				nav.clear(addr);
			}
		}
		provider.bookmarkRemoved(bookmark);
		repaintMgr.update();
	}

	/* @Override */
	protected void programDeactivated(Program program) {
		provider.setProgram(null);
		navUpdater.setProgram(null);
		program.removeListener(domainObjectListener);
		disposeAllBookmarkers();
		bookmarkMgr = null;
	}

